import Foundation

/// The allowlist of things MacSweep will ever suggest removing. Order matters: specific rules come
/// first so broad "contents of" rules don't claim the same bytes twice.
public enum CleanupCatalog {
    public static let rules: [CleanupRule] = safeRules + reviewRules

    static let safeRules: [CleanupRule] = [
        CleanupRule(id: "npm", title: "npm cache", detail: "Downloaded package tarballs. npm re-downloads on demand.",
                    safety: .safe, category: .caches, target: .paths(["~/.npm/_cacache", "~/.npm/_npx", "~/.npm/_logs"])),
        CleanupRule(id: "yarn", title: "Yarn & Bun caches", detail: "Package download caches.",
                    safety: .safe, category: .caches, target: .paths(["~/Library/Caches/Yarn", "~/.yarn/berry/cache", "~/.bun/install/cache"])),
        CleanupRule(id: "next-turbo", title: "Next.js & Turbo build output", detail: "Build artefacts. Regenerated by the next build or dev run. Folders touched in the last day are skipped in case a dev server is using them.",
                    safety: .safe, category: .caches, target: .named([".next", ".turbo", ".parcel-cache", ".nuxt", ".svelte-kit"], idleDays: 1)),
        CleanupRule(id: "gradle", title: "Gradle caches", detail: "Dependency and build caches. Gradle re-fetches as needed.",
                    safety: .safe, category: .caches, target: .paths(["~/.gradle/caches", "~/.gradle/wrapper/dists", "~/.gradle/daemon"])),
        CleanupRule(id: "xcode-derived", title: "Xcode DerivedData", detail: "Intermediate build products and indexes.",
                    safety: .safe, category: .sdks, target: .paths(["~/Library/Developer/Xcode/DerivedData"])),
        CleanupRule(id: "simulator-caches", title: "Simulator caches", detail: "Dyld and runtime caches for iOS simulators.",
                    safety: .safe, category: .sdks, target: .paths(["~/Library/Developer/CoreSimulator/Caches"])),
        CleanupRule(id: "python-tools", title: "uv, pip & Poetry caches", detail: "Downloaded wheels. Re-fetched automatically on the next install.",
                    safety: .safe, category: .caches,
                    target: .paths(["~/.cache/uv", "~/Library/Caches/pip", "~/.cache/pip", "~/Library/Caches/pypoetry", "~/.cache/pre-commit"])),
        CleanupRule(id: "homebrew", title: "Homebrew downloads", detail: "Old bottles and source tarballs.",
                    safety: .safe, category: .caches, target: .paths(["~/Library/Caches/Homebrew"])),
        CleanupRule(id: "go-build", title: "Go build cache", detail: "Compiled package cache. Rebuilt automatically.",
                    safety: .safe, category: .caches, target: .paths(["~/Library/Caches/go-build"])),
        CleanupRule(id: "cocoapods", title: "CocoaPods & Carthage caches", detail: "Downloaded pod sources.",
                    safety: .safe, category: .caches, target: .paths(["~/Library/Caches/CocoaPods", "~/Library/Caches/org.carthage.CarthageKit"])),
        CleanupRule(id: "jetbrains-caches", title: "JetBrains & VS Code caches", detail: "IDE index and update caches.",
                    safety: .safe, category: .caches,
                    target: .paths(["~/Library/Caches/JetBrains", "~/Library/Application Support/Code/Cache",
                                    "~/Library/Application Support/Code/CachedData", "~/Library/Application Support/Code/CachedExtensionVSIXs",
                                    "~/Library/Application Support/Cursor/Cache", "~/Library/Application Support/Cursor/CachedData"])),
        CleanupRule(id: "browser-caches", title: "Browser caches", detail: "Web caches for Chrome, Arc, Brave, Edge and Firefox.",
                    safety: .safe, category: .caches,
                    target: .paths(["~/Library/Caches/Google/Chrome", "~/Library/Caches/Arc", "~/Library/Caches/BraveSoftware",
                                    "~/Library/Caches/Microsoft Edge", "~/Library/Caches/Firefox"])),
        CleanupRule(id: "electron-caches", title: "Electron app caches", detail: "Web, code and GPU caches of Slack, Discord, Teams, Notion and other Electron apps. Only apps confirmed to be Chromium-based are included.",
                    safety: .safe, category: .caches,
                    target: .nested(in: "~/Library/Application Support",
                                    names: ["Cache", "Code Cache", "GPUCache", "DawnCache", "DawnGraphiteCache", "DawnWebGPUCache"],
                                    signature: ["Code Cache", "GPUCache"])),
        CleanupRule(id: "dev-tool-caches", title: "Flutter, Deno, Bazel & Composer caches", detail: "Package and build caches for other toolchains.",
                    safety: .safe, category: .caches,
                    target: .paths(["~/.pub-cache/hosted", "~/Library/Caches/deno", "~/.cache/bazel", "~/Library/Caches/composer",
                                    "~/.cache/node-gyp", "~/Library/Caches/node-gyp", "~/.cache/turbo"])),
        CleanupRule(id: "project-build-caches", title: "Project build caches", detail: "Dart/Flutter tool caches inside projects. Recreated by `flutter pub get`.",
                    safety: .safe, category: .caches, target: .named([".dart_tool"], idleDays: nil)),
        CleanupRule(id: "mail-downloads", title: "Mail attachment copies", detail: "Copies Mail saves when you open attachments. The originals stay in your mailbox.",
                    safety: .safe, category: .media,
                    target: .contents(of: "~/Library/Containers/com.apple.mail/Data/Library/Mail Downloads")),
        CleanupRule(id: "logs", title: "Logs", detail: "Application and diagnostic logs.",
                    safety: .safe, category: .system, target: .contents(of: "~/Library/Logs")),
    ]

    static let reviewRules: [CleanupRule] = [
        CleanupRule(id: "pnpm", title: "pnpm store", detail: "Projects keep working, but files are hard-linked into node_modules so less space frees than shown. Prefer `pnpm store prune`.",
                    safety: .review, category: .caches, target: .paths(["~/Library/pnpm/store", "~/.pnpm-store", "~/.local/share/pnpm/store"])),
        CleanupRule(id: "headless-browsers", title: "Puppeteer & Playwright browsers", detail: "Downloaded test browsers. Not re-downloaded automatically: run `npx playwright install` / `npx puppeteer browsers install` afterwards.",
                    safety: .review, category: .devTools,
                    target: .paths(["~/.cache/puppeteer", "~/Library/Caches/ms-playwright", "~/.cache/ms-playwright", "~/.cache/prisma"])),
        CleanupRule(id: "android", title: "Android SDK & emulators", detail: "SDK packages and emulator images. Reinstall via Android Studio.",
                    safety: .review, category: .sdks, target: .paths(["~/Library/Android/sdk", "~/.android/avd", "~/.android/cache"])),
        CleanupRule(id: "ollama", title: "Ollama models", detail: "Local LLM weights. `ollama pull` restores them.",
                    safety: .review, category: .ai, target: .paths(["~/.ollama/models"])),
        CleanupRule(id: "ai-models", title: "Hugging Face & LM Studio models", detail: "Downloaded model weights.",
                    safety: .review, category: .ai, target: .paths(["~/.cache/huggingface", "~/.lmstudio/models", "~/.cache/lm-studio/models", "~/.cache/torch"])),
        CleanupRule(id: "worktrees", title: "Claude & git worktrees", detail: "Extra checkouts created by agents. Check for unpushed work first.",
                    safety: .review, category: .code, target: .named([".claude/worktrees", ".worktrees"], idleDays: 7)),
        CleanupRule(id: "node-modules", title: "node_modules in idle projects", detail: "Dependencies of projects untouched for 30+ days.",
                    safety: .review, category: .caches, target: .named(["node_modules"], idleDays: 30)),
        CleanupRule(id: "python-venvs", title: "Python virtualenvs in idle projects", detail: "Recreate with `uv sync` or `pip install`.",
                    safety: .review, category: .caches, target: .named([".venv", "venv"], idleDays: 30)),
        CleanupRule(id: "pods", title: "CocoaPods in idle projects", detail: "Pods folders of iOS projects untouched for 30+ days. `pod install` restores them.",
                    safety: .review, category: .sdks, target: .named(["Pods"], idleDays: 30)),
        CleanupRule(id: "cocoapods-specs", title: "CocoaPods spec repos", detail: "Local copies of the CocoaPods specs index. Re-cloned on next `pod install`.",
                    safety: .review, category: .caches, target: .paths(["~/.cocoapods/repos"])),
        CleanupRule(id: "simulators", title: "iOS simulator devices", detail: "Simulator data and installed apps.",
                    safety: .review, category: .sdks, target: .paths(["~/Library/Developer/CoreSimulator/Devices"])),
        CleanupRule(id: "device-support", title: "Xcode device support & archives", detail: "Symbols for old iOS versions and archived builds.",
                    safety: .review, category: .sdks,
                    target: .paths(["~/Library/Developer/Xcode/iOS DeviceSupport", "~/Library/Developer/Xcode/watchOS DeviceSupport",
                                    "~/Library/Developer/Xcode/Archives"])),
        CleanupRule(id: "docker", title: "Docker Desktop disk image", detail: "All containers, images and volumes. Prune inside Docker first.",
                    safety: .review, category: .devTools, target: .paths(["~/Library/Containers/com.docker.docker/Data/vms"])),
        CleanupRule(id: "maven-cargo-go", title: "Maven, Cargo & Go module caches", detail: "Dependency caches. Re-downloaded on next build.",
                    safety: .review, category: .caches, target: .paths(["~/.m2/repository", "~/.cargo/registry", "~/go/pkg/mod"])),
        CleanupRule(id: "installers", title: "Old installers in Downloads", detail: "Disk images and archives older than 14 days.",
                    safety: .review, category: .media,
                    target: .files(in: "~/Downloads", extensions: ["dmg", "pkg", "zip", "iso", "xip", "tar", "gz", "tgz"], olderThanDays: 14)),
        CleanupRule(id: "app-caches", title: "Other app caches", detail: "Per-app caches in ~/Library/Caches. Apps rebuild them, sometimes slowly.",
                    safety: .review, category: .caches, target: .contents(of: "~/Library/Caches")),
        CleanupRule(id: "trash", title: "Trash", detail: "Items already in the Trash. Removing them is permanent.",
                    safety: .review, category: .system, target: .contents(of: "~/.Trash")),
    ]
}
